// Finite original editorial packet. No profile-math factory, quotas or copied tasks.
export const editorialCases=[];
const add=(subject,number,slug,prompt,answer,steps,triple,proof={})=>editorialCases.push({subject,number,slug,prompt,answer,steps,triple,proof});
const list=items=>items.map((s,i)=>`${i+1}) ${s}`).join('\n');
function select(s,n,id,stem,options,key,explanation,triple,proof={}){add(s,n,id,stem+'\n'+list(options)+'\nЗапишите номера выбранных ответов без пробелов.',key,[explanation,'Проверяем все варианты: в ответ включаются только соответствующие условию; дополнительные цифры изменяют ответ.'],triple,proof);}
function match(s,n,id,stem,objects,options,key,explanation,triple,proof={}){add(s,n,id,stem+'\n'+objects.map((x,i)=>`${'АБВГДЕ'[i]}) ${x}`).join('\n')+'\n'+list(options)+'\nЗапишите цифры в порядке букв. Цифры могут повторяться.',key,[explanation,'Сначала независимо определяем соответствие для каждой позиции, затем записываем выбранные цифры в порядке букв.'],triple,proof);}

select('chemistry',1,'sulfur-substance','Выберите два утверждения, описывающие серу как простое вещество, а не химический элемент.',[
 'В ядре атома серы находятся 16 протонов.','При обычных условиях сера представляет собой жёлтое твёрдое вещество.','Атомы серы входят в состав сульфатов.','При сгорании серы в кислороде образуется оксид серы(IV).','Сера расположена в третьем периоде.'],'24','Цвет и агрегатное состояние, а также реакция горения относятся к веществу. Число протонов, положение в таблице и присутствие атомов в соединениях относятся к элементу.',['Основные понятия химии','Элемент и простое вещество','Различение элемента и вещества']);
select('chemistry',1,'iron-substance','В каких двух высказываниях железо рассматривается как простое вещество?',[
 'Символ железа — Fe.','Железо содержится в составе гемоглобина.','Железный образец притягивается магнитом.','Железо в таблице имеет порядковый номер 26.','При контакте железной пластинки с раствором сульфата меди(II) на ней выделяется медь.'],'35','Магнитные свойства образца и взаимодействие пластинки с раствором характеризуют металлическое железо. Остальные высказывания описывают элемент или его атомы в соединениях.',['Основные понятия химии','Элемент и простое вещество','Различение элемента и вещества']);
for(const [slug,shells,element]of [['magnesium',[2,8,2],'магний'],['oxygen',[2,6],'кислород']]){
 const z=shells.reduce((a,b)=>a+b,0),period=shells.length;
 add('chemistry',2,`shells-${slug}`,`В нейтральном атоме электроны распределены по слоям от внутреннего к внешнему так: ${shells.join('; ')}. Это полное распределение всех электронов. Определите X — номер периода и Y — положительный заряд ядра в единицах элементарного заряда. Запишите подряд X и Y без разделителей.`,`${period}${z}`,[`Число занятых электронных слоёв равно ${period}; это номер периода.`,`У нейтрального атома число протонов равно числу электронов: ${shells.join(' + ')} = ${z}. Элемент — ${element}. Ответ записывается в порядке X, Y.`],['Строение вещества','Электронная оболочка','Период и заряд ядра по распределению электронов'],{kind:'electron-shells',shells});
}
match('chemistry',4,'sulfur-oxidation','Сопоставьте формулу вещества со степенью окисления серы.', ['H₂S','SO₂','Na₂SO₄'],['−2','+4','+6','0'],'123','В H₂S два атома H дают +2, значит S имеет −2. В SO₂ сумма вкладов O равна −4, поэтому S имеет +4. В Na₂SO₄: 2·(+1) + x + 4·(−2) = 0, откуда x = +6.',['Строение вещества','Степени окисления','Степень окисления по электронейтральности'],{kind:'oxidation',balances:[[2,-1],[4,1],[6,1]],values:[-2,4,6]});
match('chemistry',4,'nitrogen-oxidation','Для каждой формулы определите степень окисления азота.', ['NH₃','N₂','HNO₃'],['+5','0','−3','+3'],'321','В NH₃ сумма трёх вкладов H равна +3, поэтому N имеет −3. В простом веществе N₂ степень окисления 0. В HNO₃: +1 + x − 6 = 0, значит x = +5.',['Строение вещества','Степени окисления','Степень окисления по электронейтральности']);
select('chemistry',5,'ionic-compounds','Выберите два вещества, для которых в школьной модели характерна ионная химическая связь.',['MgCl₂','H₂','CO₂','K₂O','NH₃'],'14','MgCl₂ и K₂O образованы катионами металлов и анионами. В молекулах H₂, CO₂ и NH₃ атомы соединены ковалентными связями.',['Строение вещества','Химическая связь','Распознавание типа химической связи']);
select('chemistry',5,'nonpolar-molecules','Выберите два вещества с ковалентной неполярной связью между атомами.',['HCl','N₂','NaF','Br₂','H₂O'],'24','В N₂ и Br₂ связь образована одинаковыми атомами, поэтому электронная плотность связи не смещена к одному из них. HCl и H₂O имеют полярные ковалентные связи, NaF — ионную.',['Строение вещества','Химическая связь','Распознавание типа химической связи']);
select('chemistry',6,'magnesium-argon','Какие два свойства верны для магния и неверны для аргона? Рассматривайте нейтральные атомы и простые вещества в обычных условиях.',[
 'Элемент относится к металлам.','Атом имеет три занятых электронных слоя.','На внешнем электронном слое находятся два электрона.','В ядре атома содержится 18 протонов.','Простое вещество является одноатомным газом.'],'13','Mg — металл с распределением электронов 2,8,2. Ar — благородный газ с распределением 2,8,8. Три слоя есть у обоих элементов, поэтому второй пункт не подходит.',['Периодический закон','Свойства элементов','Сравнение электронного строения и свойств']);
select('chemistry',6,'potassium-calcium','Какие два признака характерны для калия и нехарактерны для кальция?',[
 'Относится к металлам.','Нейтральный атом содержит четыре электронных слоя.','Типичная степень окисления в соединениях равна +1.','Внешний электронный слой нейтрального атома содержит один электрон.','Типичный оксид имеет формулу CaO.'],'34','Калий относится к первой группе: имеет один внешний электрон и типичную степень окисления +1. Кальций имеет два внешних электрона и типичную степень +2. Оба элемента — металлы четвёртого периода.',['Периодический закон','Свойства элементов','Сравнение электронного строения и свойств']);
select('chemistry',7,'acid-oxide-salt','Из списка выберите кислотный оксид и соль. Запишите сначала номер кислотного оксида, затем номер соли.',['Mg(OH)₂','Na₂SO₄','CO₂','Fe','HNO₃'],'32','CO₂ — кислотный оксид, Na₂SO₄ — соль. Mg(OH)₂ является основанием, HNO₃ — кислотой, Fe — простым веществом.',['Неорганические вещества','Классы соединений','Распознавание классов веществ']);
select('chemistry',7,'base-acid','Укажите основание и кислоту, именно в таком порядке.',['SO₂','KOH','CaCl₂','H₂S','Cu'],'24','KOH — гидроксид металла, основание; H₂S — кислота. SO₂ — оксид, CaCl₂ — соль, Cu — простое вещество.',['Неорганические вещества','Классы соединений','Распознавание классов веществ']);
select('chemistry',8,'sodium-oxide-properties','Выберите два вещества, с которыми реагирует оксид натрия. Реакции рассматриваются при обычных школьных условиях.',['Вода','Медь','Раствор HCl','Аргон','Раствор NaOH'],'13','Основный оксид Na₂O реагирует с водой с образованием щёлочи и с кислотой с образованием соли и воды: Na₂O + H₂O → 2NaOH; Na₂O + 2HCl → 2NaCl + H₂O.',['Неорганические вещества','Химические свойства оксидов','Выбор реагентов для основного оксида']);
select('chemistry',8,'copper-oxide-properties','Какие два реагента взаимодействуют с оксидом меди(II)? Кислоты даны в виде водных растворов; щёлочь — водный раствор.',['H₂O','NaOH','HCl','Cu','H₂SO₄'],'35','CuO — нерастворимый основный оксид: CuO + 2HCl → CuCl₂ + H₂O; CuO + H₂SO₄ → CuSO₄ + H₂O. В принятой школьной модели с водой и щёлочью он не реагирует.',['Неорганические вещества','Химические свойства оксидов','Выбор реагентов для основного оксида']);
match('chemistry',9,'reaction-products-a','Соотнесите реагенты с продуктами. Щёлочь взята в избытке; соли — нормальные.', ['MgO + HNO₃','Zn + HCl','SO₃ + NaOH'],['ZnCl₂ и H₂','Na₂SO₄ и H₂O','Mg(NO₃)₂ и H₂O','Na₂SO₃ и H₂O','Mg и NO₂'],'312','MgO + 2HNO₃ → Mg(NO₃)₂ + H₂O; Zn + 2HCl → ZnCl₂ + H₂; SO₃ + 2NaOH → Na₂SO₄ + H₂O. Последняя реакция не меняет степень окисления серы +6.',['Химические реакции','Продукты реакций','Соответствие реагентов и продуктов']);
match('chemistry',9,'reaction-products-b','Установите продукты реакций. Для первой пары CO₂ взят без избытка относительно образования средней соли.', ['CO₂ + Ca(OH)₂','CuO + H₂SO₄','Ca + H₂O'],['Ca(OH)₂ и H₂','CuSO₄ и H₂O','CaCO₃ и H₂O','CaO и H₂','Cu и SO₂'],'321','CO₂ + Ca(OH)₂ → CaCO₃↓ + H₂O; CuO + H₂SO₄ → CuSO₄ + H₂O; Ca + 2H₂O → Ca(OH)₂ + H₂↑. Ограничение на CO₂ исключает образование гидрокарбоната.',['Химические реакции','Продукты реакций','Соответствие реагентов и продуктов']);
match('chemistry',10,'reagent-pairs-a','Для каждого вещества выберите пару реагентов, с КАЖДЫМ из которых оно реагирует. Растворимые вещества даны в водных растворах; CuO — твёрдое вещество.', ['NaCl','CuO','CO₂'],['AgNO₃; Pb(NO₃)₂','HCl; разбавленная H₂SO₄','Ca(OH)₂; NaOH','H₂O; KNO₃'],'123','Хлорид даёт осадки AgCl и PbCl₂. CuO с каждой из двух кислот образует соль и воду. CO₂ с основаниями образует соли; воды самой по себе недостаточно для подходящей пары из пункта 4. Для каждой буквы остальные пары не обеспечивают обе реакции.',['Химические реакции','Реакционная способность','Выбор пары взаимодействующих реагентов']);
match('chemistry',10,'reagent-pairs-b','Для каждого вещества подберите пару, с обоими реагентами которой оно взаимодействует. Соли, кислоты и основания даны в водных растворах.', ['FeO','SO₂','Na₂SO₄'],['KOH; Ca(OH)₂','BaCl₂; Ba(NO₃)₂','HCl; разбавленная H₂SO₄','NaCl; KNO₃'],'312','FeO реагирует с обеими кислотами, образуя соли Fe(II) и воду. SO₂ связывается обеими щелочными средами с образованием сульфитов при достаточном количестве основания. Сульфат натрия образует осадок BaSO₄ с каждым из двух солевых растворов бария.',['Химические реакции','Реакционная способность','Выбор пары взаимодействующих реагентов']);
select('chemistry',11,'redox-reaction-selection-a','Выберите две окислительно-восстановительные реакции из перечисленных схем.', ['Mg + O₂ → MgO','HCl + KOH → KCl + H₂O','Fe + CuSO₄ → FeSO₄ + Cu','CaO + H₂O → Ca(OH)₂','NaCl + AgNO₃ → AgCl + NaNO₃'],'13','В первой схеме Mg меняет степень окисления 0 → +2, O: 0 → −2. В третьей Fe: 0 → +2, Cu: +2 → 0. В остальных схемах степени окисления элементов сохраняются. Схемы здесь служат для классификации; в первой полное уравнение 2Mg + O₂ → 2MgO.',['Химические реакции','Окисление и восстановление','Распознавание ОВР по изменению степеней окисления']);
select('chemistry',11,'redox-reaction-selection-b','В каких двух схемах реакции изменяются степени окисления элементов?', ['Na₂CO₃ + HCl → NaCl + CO₂ + H₂O','H₂O₂ → H₂O + O₂','CuO + HCl → CuCl₂ + H₂O','Fe₂O₃ + CO → Fe + CO₂','K₂O + H₂SO₄ → K₂SO₄ + H₂O'],'24','В разложении пероксида O меняет −1 на −2 и 0; уравнение 2H₂O₂ → 2H₂O + O₂. При восстановлении оксида Fe: +3 → 0, C: +2 → +4; полное уравнение Fe₂O₃ + 3CO → 2Fe + 3CO₂. Остальные схемы не являются ОВР.',['Химические реакции','Окисление и восстановление','Распознавание ОВР по изменению степеней окисления']);
match('chemistry',12,'reaction-signs-a','Соотнесите взаимодействующие вещества с главным наблюдаемым признаком. Растворимые реагенты — водные растворы.', ['Na₂SO₄ и BaCl₂','Mg и разбавленная HCl','CuSO₄ и NaOH'],['Голубой осадок','Выделение бесцветного газа','Белый осадок','Бурый осадок','Выделение фиолетовых паров'],'321','Образуются соответственно белый BaSO₄, газ H₂ и голубой Cu(OH)₂. Уравнения: Na₂SO₄ + BaCl₂ → BaSO₄↓ + 2NaCl; Mg + 2HCl → MgCl₂ + H₂↑; CuSO₄ + 2NaOH → Cu(OH)₂↓ + Na₂SO₄.',['Химические реакции','Наблюдаемые признаки','Соответствие реагентов и наблюдения']);
match('chemistry',12,'reaction-signs-b','Установите признак взаимодействия каждой пары водных растворов.', ['Na₂CO₃ и HCl','AgNO₃ и KCl','FeCl₃ и NaOH'],['Бурый осадок','Белый осадок','Выделение бесцветного газа','Голубой осадок','Изменений не наблюдается'],'321','Карбонат с кислотой выделяет CO₂; ионы Ag⁺ и Cl⁻ дают белый AgCl; Fe³⁺ с OH⁻ образует бурый Fe(OH)₃. Для кислоты предполагается достаточное количество, для гидроксидов — образование осадка.',['Химические реакции','Наблюдаемые признаки','Соответствие реагентов и наблюдения']);
select('chemistry',13,'calcium-dissociation','Какие два утверждения описывают полную диссоциацию 1 моль CaCl₂ в воде?', ['Образуется 1 моль Ca²⁺.','Образуется 2 моль Ca²⁺.','Образуется 2 моль Cl⁻.','Образуется 1 моль Cl⁻.','Образуются молекулы Cl₂.'],'13','CaCl₂ → Ca²⁺ + 2Cl⁻. Коэффициенты показывают количества ионов: 1 моль катионов кальция и 2 моль хлорид-ионов. Суммарный заряд +2 − 2 = 0.',['Растворы','Электролитическая диссоциация','Ионы и их количество']);
select('chemistry',13,'potassium-sulfate-dissociation','При полной диссоциации 1 моль K₂SO₄ какие два результата верны?', ['Образуется 1 моль K⁺.','Образуется 1 моль SO₄²⁻.','Образуется 2 моль K⁺.','Образуется 4 моль O²⁻.','Образуется 2 моль SO₄²⁻.'],'23','K₂SO₄ → 2K⁺ + SO₄²⁻. Кислород не отделяется от многоатомного сульфат-иона. Заряд двух катионов +2 компенсируется зарядом одного аниона −2.',['Растворы','Электролитическая диссоциация','Ионы и их количество']);
select('chemistry',14,'carbonate-net-ionic','Выберите две растворимые исходные вещества, взаимодействию которых соответствует сокращённое уравнение CO₃²⁻ + 2H⁺ → CO₂ + H₂O.', ['NaCl','KOH','HCl','Cu','Na₂CO₃','NaNO₃'],'35','HCl даёт H⁺, Na₂CO₃ — CO₃²⁻. Ионы Na⁺ и Cl⁻ остаются наблюдателями: Na₂CO₃ + 2HCl → 2NaCl + CO₂↑ + H₂O. Другие пары не дают указанное сокращённое уравнение.',['Растворы','Ионные уравнения','Подбор веществ по сокращённому уравнению']);
select('chemistry',14,'silver-net-ionic','Какие два вещества в водном растворе дают реакцию Ag⁺ + Cl⁻ → AgCl↓?', ['KNO₃','AgNO₃','CuO','KCl','NaOH','H₂SO₄'],'24','AgNO₃ поставляет Ag⁺, KCl — Cl⁻. Обмен даёт AgCl↓ и KNO₃. Ни нитрат-ион, ни калий в сокращённую запись не входят.',['Растворы','Ионные уравнения','Подбор веществ по сокращённому уравнению']);
for(const [slug,changes]of [['a',[[2,3],[0,-2],[6,4]]],['b',[[-1,0],[3,2],[0,2]]]]){
 const key=changes.map(([a,b])=>b>a?'1':'2').join('');
 const elements=slug==='a'?['Fe','O','S']:['Cl','Fe','Mg'];
 match('chemistry',15,`electron-process-${slug}`,'Соотнесите изменение степени окисления элемента с названием процесса. Числа в скобках обозначают степени окисления атомов данного элемента.',changes.map(([a,b],i)=>`${elements[i]}(${a>0?'+':''}${a}) → ${elements[i]}(${b>0?'+':''}${b})`),['Окисление','Восстановление'],key,'Рост степени окисления означает отдачу электронов (окисление), уменьшение — принятие электронов (восстановление). Проверяем знак разности конечной и начальной степеней для каждой строки.',['Химические реакции','Окисление и восстановление','Направление переноса электронов'],{kind:'electron-direction',changes});
}
select('chemistry',16,'lab-safety-a','Отметьте верные суждения о работе в школьной химической лаборатории.', ['Защитные очки уменьшают риск попадания брызг в глаза.','Вещества можно пробовать на вкус, если они похожи на пищевые.','Открытый конец нагреваемой пробирки направляют от себя и других людей.','Избыток взятого реактива всегда возвращают в общий флакон.','При попадании неизвестного вещества на кожу нужно немедленно сообщить учителю.'],'135','Очки защищают глаза; пробирку направляют от людей; о происшествии сразу сообщают учителю. Пробовать реактивы запрещено, а возврат остатка загрязняет общий реактив.',['Методы химии','Лабораторная безопасность','Безопасное обращение с веществами']);
select('chemistry',16,'lab-safety-b','Какие правила школьного химического кабинета сформулированы верно?', ['Неизвестные жидкости можно смешивать, чтобы определить их цвет.','Перед использованием флакона нужно проверить этикетку.','О повреждённой лабораторной посуде следует сообщить учителю и не использовать её.','Еду можно хранить рядом с реактивами в одинаковой упаковке.','При нагревании легковоспламеняющейся жидкости допустимо открытое пламя.'],'23','Маркировка предотвращает подмену вещества; повреждённая посуда опасна. Самовольное смешивание, хранение пищи с реактивами и открытое пламя при работе с легковоспламеняющимися жидкостями недопустимы.',['Методы химии','Лабораторная безопасность','Безопасное обращение с веществами']);
match('chemistry',17,'identify-solutions-a','Подберите реагент для различения двух растворов из каждой пары. Учитывайте выделение газа или появление осадка только в одном из растворов пары. Для солей аммония со щёлочью учитывайте выделение аммиака при нагревании. Концентрации достаточны для образования предусмотренных осадков.', ['NH₄Cl и NaCl','Na₂CO₃ и Na₂SO₄','Na₂SO₄ и NaNO₃'],['NaOH','HCl','BaCl₂','NaNO₃'],'123','NH₄Cl со щёлочью при нагревании выделяет NH₃, NaCl — нет. Карбонат с HCl выделяет CO₂, сульфат — нет. BaCl₂ осаждает сульфат из третьей пары. С барием обе соли второй пары дают белые осадки, что по заданному критерию не позволяет их различить.',['Методы химии','Качественные реакции','Различение растворов одним реагентом']);
match('chemistry',17,'identify-solutions-b','Для каждой пары водных растворов выберите реагент, который вызывает появление осадка или выделение газа ТОЛЬКО в одном из двух растворов пары. Исходную окраску и различие цветов осадков не используйте. Концентрации достаточны для выпадения соответствующих осадков, в том числе солей серебра.', ['Na₂CO₃ и NaCl','CuSO₄ и Na₂SO₄','KBr и KNO₃'],['AgNO₃','NaOH','Разбавленная HCl','KNO₃'],'321','Карбонат при добавлении HCl выделяет CO₂, хлорид — нет. Cu²⁺ образует с OH⁻ осадок, сульфат натрия — нет. Br⁻ с Ag⁺ даёт осадок AgBr, нитрат калия не даёт осадка. AgNO₃ осаждает обе соли первой пары и, при указанных концентрациях, сульфат из обоих растворов второй пары, поэтому по заданному критерию для них не подходит.',['Методы химии','Качественные реакции','Различение растворов одним реагентом']);

match('biology',2,'kingdom-organisms-a','Соотнесите организмы с царствами в школьной классификации.', ['Берёза повислая','Кишечная палочка','Шампиньон двуспоровый','Дождевой червь'],['Бактерии','Грибы','Растения','Животные'],'3124','Берёза — растение; кишечная палочка — бактерия; шампиньон — гриб; дождевой червь — животное. Не смешиваем царство и среду обитания организма.',['Многообразие организмов','Царства живой природы','Соответствие организма и царства']);
match('biology',2,'kingdom-organisms-b','Установите царство для каждого организма. Используйте школьную классификацию.', ['Молочнокислая бактерия','Пекарские дрожжи','Сосна обыкновенная','Паук-крестовик'],['Животные','Растения','Грибы','Бактерии'],'4321','Бактерия относится к бактериям, дрожжи — одноклеточные грибы, сосна — растение, паук — животное. Одноклеточность сама по себе не означает принадлежность к бактериям.',['Многообразие организмов','Царства живой природы','Соответствие организма и царства']);
select('biology',8,'table-organelle','Заполните единственный пропуск в авторской таблице.\nСтруктура клетки | Основная функция\nРибосома | Сборка белка\n… | Хранение основной наследственной информации в типичной клетке эпителия человека\nВыберите один ответ.', ['Хлоропласт','Клеточная стенка','Ядро','Сократительная вакуоль'],'3','В ядре клетки эпителия находится основная часть ДНК. Рибосомы синтезируют белок; хлоропласты и клеточная стенка для указанной животной клетки не характерны.',['Клетка','Структура и функция','Пропуск в биологической таблице']);
select('biology',8,'table-tissue','Определите пропуск в таблице по связи «ткань — функция».\nТкань | Функция\nМышечная | Сокращение\n… | Восприятие раздражения и проведение нервных импульсов\nВыберите один ответ.', ['Нервная','Костная','Жировая','Покровный эпителий'],'1','Нервная ткань образована нейронами и вспомогательными клетками. Её функции связаны с восприятием, обработкой и проведением сигналов; сокращение характеризует мышечную ткань.',['Организм человека','Ткани','Пропуск в биологической таблице']);
add('biology',10,'leaf-text','Вставьте четыре пропуска в авторский текст о листе. Запишите цифры в порядке А, Б, В, Г.\nВ клетках зелёной мякоти листа находятся (А) — органоиды, в которых на свету образуются органические вещества. Одно из исходных веществ поступает из воздуха: это (Б). Образующийся в ходе фотосинтеза газ (В) может выходить через устьица. Водяной пар также покидает лист: этот процесс называется (Г). Вода доставляется в лист по проводящей ткани. При этом лист не только фотосинтезирует: его живые клетки постоянно расходуют органические вещества на жизнедеятельность и дыхание, в том числе ночью.\n'+list(['Кислород','Хлоропласты','Транспирация','Азот','Углекислый газ','Рибосомы','Опыление','Водород']),'2513',['Хлоропласты — место фотосинтеза; из воздуха поступает углекислый газ. Выделяется кислород, испарение воды растением называется транспирацией.','По порядку пропусков: 2, 5, 1, 3. Фотосинтез и дыхание — разные процессы.'],['Растения','Фотосинтез и испарение','Термины в связном биологическом тексте']);
add('biology',10,'digestion-text','Заполните пропуски А–Г в авторском тексте. Запишите соответствующие цифры подряд.\nПереваривание пищи начинается в ротовой полости, где (А) измельчают её механически. Язык перемешивает пищу со слюной. В слюне присутствует фермент, начинающий расщепление (Б). Далее пищевой комок проходит по пищеводу в (В), где среда обычно кислая. Окончательное расщепление питательных веществ и всасывание большинства продуктов переваривания происходят в (Г). Стенки этого отдела имеют ворсинки, увеличивающие поверхность всасывания. Остатки пищи переходят в следующий отдел, где продолжается всасывание воды. Разные участки пищеварительной системы выполняют взаимосвязанные функции.\n'+list(['Белки','Желудок','Тонкая кишка','Крахмал','Лёгкие','Зубы','Почки','Толстая кишка']),'6423',['Зубы механически измельчают пищу. Амилаза слюны начинает гидролиз крахмала. Пищевод ведёт в желудок; основные продукты переваривания всасываются в тонкой кишке.','Последовательность выбранных слов: зубы, крахмал, желудок, тонкая кишка — 6423.'],['Организм человека','Пищеварение','Термины в связном биологическом тексте']);
match('biology',11,'development-types','Установите тип развития для каждого животного.', ['Озёрная лягушка','Курица','Капустная белянка','Домашняя кошка','Окунь'],['Прямое','Непрямое, с личиночной стадией'],'21212','У лягушки есть головастик, у белянки — гусеница, у окуня — личинка. У курицы и кошки отсутствует отдельная личиночная стадия. Яйцекладность птиц сама по себе не означает непрямого развития.',['Животные','Развитие организмов','Соответствие животного и типа развития']);
match('biology',11,'plant-groups','Сопоставьте растения с отделами школьной классификации.', ['Сосна','Ландыш','Лиственница','Горох','Тюльпан'],['Голосеменные','Покрытосеменные'],'12122','Сосна и лиственница — голосеменные хвойные растения. Ландыш, горох и тюльпан — цветковые, или покрытосеменные. Листопадность лиственницы не меняет её принадлежности к голосеменным.',['Растения','Отделы растений','Соответствие растения и отдела']);
select('biology',12,'bacteria-judgments','Оцените два суждения.\nА. У типичной бактериальной клетки отсутствует оформленное мембранное ядро.\nБ. У типичной бактериальной клетки имеются рибосомы.\nВыберите один ответ.',['Верно только А','Верно только Б','Верны оба суждения','Оба суждения неверны'],'3','Бактерии — прокариоты: их ДНК не заключена в мембранное ядро. Белок синтезируется на имеющихся рибосомах. Оба утверждения верны.',['Клетка','Прокариоты','Оценка двух биологических суждений']);
select('biology',12,'fungi-judgments','Верны ли суждения о грибах?\nА. Все грибы образуют органические вещества из углекислого газа в ходе фотосинтеза.\nБ. В состав клеточной стенки грибов входит хитин.\nВыберите один ответ.',['Верно только А','Верно только Б','Верны оба суждения','Оба суждения неверны'],'2','Грибы гетеротрофны и не фотосинтезируют. Для их клеточных стенок характерен хитин, поэтому верно только Б.',['Многообразие организмов','Грибы','Оценка двух биологических суждений']);
select('biology',15,'sweating-function','После физической нагрузки в жарком помещении пот испаряется с кожи. Как это помогает организму поддерживать температуру? Выберите одно объяснение.', ['Испарение полностью прекращает клеточное дыхание.','При испарении воды от поверхности кожи отводится тепло.','Пот превращает солнечную энергию в белок.','Испарение делает кровь неспособной переносить кислород.'],'2','Для перехода воды в пар требуется энергия, которая отводится от кожи. Это один из механизмов теплоотдачи; клеточное дыхание и перенос кислорода при этом не прекращаются.',['Организм человека','Терморегуляция','Объяснение физиологического процесса']);
select('biology',15,'breathing-exercise','Во время бега работающие мышцы активнее расходуют кислород и выделяют углекислый газ. Почему учащение дыхания помогает обеспечить работу мышц? Выберите один ответ.', ['Оно само по себе заменяет питание мышечных клеток.','Оно превращает углекислый газ в кислород в лёгких.','Оно усиливает вентиляцию лёгких и поддерживает обмен газов с кровью.','Оно прекращает движение крови через лёгкие.'],'3','Усиление вентиляции поддерживает поступление кислорода к альвеолам и удаление углекислого газа. Затем газы переносятся кровью; кислород не образуется в лёгких из CO₂.',['Организм человека','Дыхание','Объяснение физиологического процесса']);
select('biology',17,'erythrocyte-traits','Выберите три признака, характерные для зрелых эритроцитов человека в норме.', ['Содержат гемоглобин.','Участвуют в переносе кислорода.','Образуют защитные антитела.','Имеют крупное оформленное ядро.','Обычно имеют форму двояковогнутого диска.','Образуют кость.'],'125','Гемоглобин обеспечивает перенос кислорода, двояковогнутая форма увеличивает отношение поверхности к объёму. Зрелые эритроциты человека безъядерны; антитела не являются их продуктом.',['Организм человека','Кровь','Множественный выбор признаков клеток человека']);
select('biology',17,'skeletal-muscle-traits','Какие три характеристики относятся к скелетной мышечной ткани человека?', ['Волокна имеют поперечную исчерченность.','Образует слизистую оболочку желудка.','Участвует в движении костей скелета.','Основные клетки выделяют антитела.','Образует наружный роговой слой кожи.','Её сокращения в обычных условиях могут подчиняться воле человека.'],'136','Скелетная мышечная ткань поперечнополосатая, обеспечивает движения скелета и произвольные сокращения. Эпителий слизистых, клетки иммунной системы и роговой слой к ней не относятся.',['Организм человека','Мышечная ткань','Множественный выбор признаков тканей человека']);
match('biology',18,'circulation-types','Соотнесите сосуды с кругами кровообращения человека.', ['Лёгочная артерия','Аорта','Лёгочная вена','Верхняя полая вена','Нижняя полая вена','Капилляры альвеол'],['Большой круг','Малый круг'],'212112','Лёгочные артерии, лёгочные вены и капилляры вокруг альвеол входят в малый круг. Аорта и полые вены — в большой. Круг определяется маршрутом крови, а не только её насыщением кислородом.',['Организм человека','Кровообращение','Соответствие структуры и системы']);
match('biology',18,'nervous-parts','Распределите структуры между центральной и периферической нервной системой человека.', ['Головной мозг','Черепные нервы','Спинной мозг','Спинномозговые нервы','Нервные узлы','Мозжечок'],['Центральная','Периферическая'],'121221','К центральной нервной системе относятся головной и спинной мозг, в том числе мозжечок как отдел головного мозга. Нервы и нервные узлы относятся к периферической системе.',['Организм человека','Нервная система','Соответствие структуры и системы']);

const social=(n,id,stem,options,key,explanation,triple)=>select('social-studies',n,id,stem+' Выберите один правильный ответ.',options,key,explanation,triple);
social(4,'culture-scientific-test','Исследователь выдвинул предположение о памяти и проверил его в воспроизводимом опыте. Какой признак науки проявился?', ['Опора только на личный вкус','Проверка гипотезы с помощью доказательств','Обязательное поклонение сверхъестественным силам','Передача информации только художественным образом'],'2','Научные гипотезы проверяют наблюдением, экспериментом и логическими аргументами. Личный вкус, религиозная вера и художественный образ не заменяют такую проверку.',['Духовная культура','Наука','Распознавание признаков науки']);
social(4,'culture-art','Постановщик спектакля передаёт идею через сценические образы, интонации и музыку. К какой форме духовной культуры относится эта деятельность?', ['Наука','Мораль','Искусство','Право'],'3','Художественные образы и эстетическое освоение действительности — признаки искусства. Здесь не описаны получение научного знания или установление правовых норм.',['Духовная культура','Искусство','Распознавание форм духовной культуры']);
social(5,'socialization-responsibility','Подросток научился выполнять обещания и учитывать интересы других участников школьного проекта. Какое понятие характеризует приобретённые социально значимые качества?', ['Индивид как отдельный представитель биологического вида','Организм','Популяция','Личность'],'4','Личность характеризуется социальными качествами, которые формируются в общении и деятельности. Указаны ответственность и учёт интересов других.',['Человек и общество','Социализация','Социальные качества личности']);
social(5,'social-role','Ученица одновременно участвует в семейной жизни как дочь, в классе как староста и в команде как капитан. Как называются связанные с этими позициями ожидаемые образцы поведения?', ['Социальные роли','Биологические рефлексы','Природные ресурсы','Технические нормы производства'],'1','Социальная роль — ожидаемое поведение человека в соответствии с занимаемой социальной позицией. Один человек способен исполнять несколько ролей.',['Человек и общество','Социальные роли','Социальные позиции и ожидаемое поведение']);
social(6,'mobility-judgments','Оцените суждения о социальной мобильности.\nА. Повышение работника до руководителя отдела является примером вертикальной мобильности.\nБ. Переход специалиста на такую же должность в другую организацию без изменения статуса может быть горизонтальной мобильностью.', ['Верно только А','Верно только Б','Верны оба суждения','Оба суждения неверны'],'3','В первом случае происходит повышение статуса. Во втором условие прямо исключает изменение статуса, поэтому перемещение горизонтальное.',['Социальные отношения','Социальная мобильность','Оценка двух социальных суждений']);
social(6,'education-judgments','Верны ли суждения об образовании?\nА. Образование связано только с передачей профессиональных навыков и не влияет на социализацию.\nБ. Получать новые знания человек может и после окончания школы.', ['Верно только А','Верно только Б','Верны оба суждения','Оба суждения неверны'],'2','Образование передаёт знания, нормы и ценности и тем самым участвует в социализации. Учёба возможна в течение жизни, а не только до окончания школы.',['Духовная культура','Образование','Оценка двух социальных суждений']);
social(10,'market-price-signal','Верны ли суждения о рынке?\nА. Рыночная цена может служить сигналом об изменении спроса и предложения.\nБ. Конкуренция означает, что продавцы всегда обязаны устанавливать одинаковые цены.', ['Верно только А','Верно только Б','Верны оба суждения','Оба суждения неверны'],'1','Цена отражает соотношение спроса и предложения. Конкуренция предполагает соперничество, а не обязанность одинаковых цен.',['Экономика','Рынок','Оценка экономических суждений']);
social(10,'money-functions','Покупатель сравнил цены двух товаров, выраженные в рублях, но ничего не купил. Какую функцию денег иллюстрирует сравнение?', ['Средство обращения','Мера стоимости','Мировые деньги','Средство платежа'],'2','Выражение и сравнение цен — функция меры стоимости. Передачи денег или исполнения долгового обязательства в условии нет.',['Экономика','Деньги','Распознавание функций денег']);
social(11,'democracy-signs','В условном государстве граждане выбирают представителей на конкурентных выборах; оппозиция может законно критиковать власть. Какой режим соответствует этим признакам?', ['Тоталитарный','Авторитарный','Демократический','Наследственная диктатура'],'3','Конкурентные выборы и легальная оппозиция относятся к демократическим механизмам. В условии речь о режиме, а не о форме территориального устройства.',['Политика','Политические режимы','Режим по совокупности признаков']);
social(11,'federation-sign','Территория условной страны состоит из субъектов, которые имеют собственные органы государственной власти и разграниченные с центром полномочия. Какова форма территориального устройства?', ['Федерация','Монархия','Республика','Демократия'],'1','Федерация описывает территориальное устройство с субъектами и разделением полномочий. Монархия и республика — формы правления, демократия — характеристика режима.',['Политика','Государственное устройство','Различение характеристик государства']);
social(13,'personal-right','К какой группе прав человека относится право на жизнь?', ['Политические','Экономические','Личные гражданские','Трудовые'],'3','Право на жизнь защищает существование и личную неприкосновенность человека, поэтому относится к личным гражданским правам. Оно не связано с участием в управлении государством или трудовым договором.',['Право','Права человека','Классификация прав']);
social(13,'political-right','Какое из перечисленных прав связано прежде всего с участием граждан в управлении государством?', ['Право на отдых','Избирательное право','Право на охрану здоровья','Право на жилище'],'2','Избирательные права позволяют участвовать в формировании публичной власти и относятся к политическим. Остальные варианты относятся к социальной и экономической сфере.',['Право','Права человека','Классификация прав']);
social(15,'civil-situation','Два гражданина заключили договор купли-продажи велосипеда и спорят об исполнении его условий. Какая отрасль права регулирует описанные имущественные отношения?', ['Трудовое','Конституционное','Уголовное','Гражданское'],'4','Договорные имущественные отношения равных участников регулирует гражданское право. В условии нет трудового договора, преступления или вопроса об устройстве государства.',['Право','Отрасли права','Правовая ситуация и отрасль']);
social(15,'labour-situation','Совершеннолетний работник заключил трудовой договор с организацией. Возник спор о предоставлении ежегодного оплачиваемого отпуска. Нормы какой отрасли применяются?', ['Трудового права','Семейного права','Уголовного права','Международного публичного права'],'1','Отношения работника и работодателя, включая предусмотренный трудовыми отношениями отпуск, регулируются трудовым правом. Конкретные сроки и процедура разрешения спора здесь не спрашиваются.',['Право','Отрасли права','Правовая ситуация и отрасль']);
social(16,'executive-body','Какой из органов Российской Федерации осуществляет исполнительную власть?', ['Государственная Дума','Конституционный Суд','Правительство','Совет Федерации'],'3','Правительство относится к исполнительной власти. Государственная Дума и Совет Федерации — палаты парламента; Конституционный Суд осуществляет судебную власть.',['Политика','Органы государственной власти РФ','Разделение властей']);
social(16,'constitution-supremacy','Какой нормативный правовой акт имеет высшую юридическую силу в Российской Федерации?', ['Приказ министерства','Конституция РФ','Региональный закон','Постановление местной администрации'],'2','Конституция РФ закрепляет основы правового порядка и обладает высшей юридической силой. Акты иных уровней не должны ей противоречить.',['Право','Конституционные основы','Место Конституции в системе права']);
